'use strict';
const $=s=>document.querySelector(s), KEY='abuad-life-v1';
const places=[
{id:'hostel',name:'Student hostel',icon:'🏡',x:24,y:24,desc:'Your little corner of campus. Rest, reset, and catch up with your roommates.',actions:[['nap','Take a power nap','☁',1,0,{energy:28,hunger:-5},'A good nap can fix almost anything.'],['call','Call home','☎',1,0,{mood:15,social:5},'A familiar voice. You feel a little lighter.'],['wash','Freshen up','🫧',1,0,{mood:8,energy:5},'Fresh clothes. Fresh perspective.']]},
{id:'library',name:'University library',icon:'📚',x:69,y:22,desc:'Quiet corners, big ideas. A little consistency goes a long way.',actions:[['study','Focused study session','✎',2,0,{knowledge:12,energy:-17,hunger:-8,mood:-3},'Two focused hours. The difficult topic finally clicks.'],['group','Join a study group','☷',2,0,{knowledge:8,social:10,energy:-12,hunger:-8},'You explain a concept and learn something new yourself.']]},
{id:'lecture',name:'Lecture theatre',icon:'🏛️',x:48,y:44,desc:'Show up for the future you. One lecture and one assignment per day.',actions:[['lecture','Attend a lecture','▣',2,0,{knowledge:10,attendance:1,energy:-14,hunger:-8},'You took useful notes and earned an attendance mark.'],['assignment','Complete an assignment','✍',2,0,{knowledge:8,assignments:1,energy:-15,mood:-3},'Submitted before the deadline. That feels good.']]},
{id:'cafe',name:'Campus cafeteria',icon:'🍲',x:20,y:66,desc:'A plate of something good and a chance to slow down. These are fictional game prices.',actions:[['rice','Jollof & chicken','🍛',1,1200,{hunger:48,mood:8,energy:5},'Smoky jollof. Exactly what you needed.'],['snack','Grab a quick snack','🥪',1,400,{hunger:22,mood:3},'A little fuel for your next move.'],['meal','Budget student meal','🥣',1,200,{hunger:18},'Simple, filling, and friendly to your wallet.']]},
{id:'hub',name:'Innovation hub',icon:'💻',x:79,y:60,desc:'Build your skills. Find your people. Turn a little talent into a little naira.',actions:[['gig','Complete a freelance gig','⌨',3,0,{money:1800,skills:9,energy:-22,hunger:-12,mood:3},'Your client loves it. ₦1,800 added to your wallet.'],['workshop','Attend a skills workshop','⚡',2,300,{skills:15,social:5,energy:-10},'New skills unlocked. Keep showing up.']]},
{id:'sports',name:'Sports ground',icon:'⚽',x:51,y:81,desc:'Move your body, clear your head. There is life outside the lecture theatre.',actions:[['football','Play a friendly match','⚽',2,0,{mood:22,social:8,energy:-18,hunger:-12},'A last-minute goal. The group chat will hear about this.'],['walk','Take an evening walk','🌿',1,0,{mood:13,energy:-5},'You breathe deeply. Campus looks good in this light.']]}
];
expandCampus(places);
applyWorkstackMap(places);
const people=[{name:'Tomi',icon:'👩🏾‍💻',role:'The creative coder',text:'Always has a side project and an extra seat at the ICT Building.',place:'hub'},{name:'Dami',icon:'🧑🏾‍🎓',role:'Your study partner',text:'Colour-coded notes, big ambitions, and surprisingly good advice.',place:'library'},{name:'Zara',icon:'👩🏽‍🎨',role:'The campus connector',text:'Knows the next event before the posters are up.',place:'cafe'}];
let zone='student',campusView='map',campusQuery='';
let state=null,tab='campus',selected='hostel',audioOn=false,audioCtx,toastTimer;
const fresh=(name,course,avatar)=>({version:1,name,course,avatar,location:'hostel',day:1,hour:8,money:12000,energy:85,hunger:80,mood:75,social:20,knowledge:15,skills:0,attendance:0,assignments:0,friends:[0,0,0],visits:[],actions:[],daily:{},logs:[],finished:false,events:0});
function save(){syncStudentLife();try{localStorage.setItem(KEY,JSON.stringify(state));$('#saveStatus').textContent='✓ Saved on this browser'}catch{$('#saveStatus').textContent='Saving unavailable · keep this tab open'}}
function clamp(v){return Math.max(0,Math.min(100,v))}
function money(v){return '₦'+v.toLocaleString('en-NG')}
function log(t){state.logs.unshift({day:state.day,hour:state.hour,text:t});state.logs=state.logs.slice(0,150)}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function ping(){if(!audioOn)return;try{audioCtx ||= new (window.AudioContext||window.webkitAudioContext)();const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.connect(g);g.connect(audioCtx.destination);o.frequency.value=660;g.gain.setValueAtTime(.025,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+.2);o.start();o.stop(audioCtx.currentTime+.2)}catch{}}
function show(html){$('#modal').classList.remove('social-modal');$('#modal').classList.remove('student-phone');$('#modal').innerHTML=html;if(!$('#modal').open)$('#modal').showModal()}
function close(){$('#modal').close()}
function intro(){let avatar='🧑🏾‍🎓';show(`<div class="eyebrow">YOUR CAMPUS. YOUR STORY.</div><h2>A fresh start.<br>A life to make your own.</h2><p>Welcome to Abuad Life. Spend a fictional 28-day semester balancing your grades, friendships, wellbeing, and wallet. Your student phone unlocks projects, societies, shopping, savings, and hostel upgrades.</p><form id="character"><label for="name">What should we call you?</label><input id="name" maxlength="24" placeholder="Enter your first name" required autocomplete="given-name"><label for="course">Choose your department</label><select id="course"><option>Computer Science</option><option>Engineering</option><option>Medicine</option><option>Law</option><option>Pharmacy</option><option>Agriculture</option><option>Business Administration</option><option>Nursing</option><option>Arts & Sciences</option></select><label>Pick your character</label><div class="choices">${['🧑🏾‍🎓','👩🏾‍🎓','👨🏽‍🎓','👩🏽‍🎓'].map((a,i)=>`<button type="button" data-avatar="${a}" class="${i===0?'chosen':''}" aria-label="Character ${i+1}" aria-pressed="${i===0}">${a}</button>`).join('')}</div><button class="primary" type="submit">Start my campus story →</button></form><p style="font-size:10px">Solo campus story · live player chat · virtual currency<br>Location markers from the supplied WorkStack map; fictional game activities; not official ABUAD rules or prices.</p>`);document.querySelectorAll('[data-avatar]').forEach(b=>b.onclick=()=>{avatar=b.dataset.avatar;document.querySelectorAll('[data-avatar]').forEach(x=>{x.classList.toggle('chosen',x===b);x.setAttribute('aria-pressed',x===b)})});$('#character').onsubmit=e=>{e.preventDefault();const name=$('#name').value.trim();if(!name)return;state=fresh(name,$('#course').value,avatar);log('Moved into the hostel. A new story begins.');close();save();render();toast('Welcome to campus, '+name+'! Pick a place to get started.')};$('#modal').oncancel=e=>{if(!state)e.preventDefault()}}
function escapeHtml(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function gpa(){return Math.min(5,(state.knowledge*.027+Math.min(state.attendance,18)/18*1.1+Math.min(state.assignments,10)/10*.9))}
function goals(){return[{title:'Show up for yourself',text:'Attend 12 lectures this semester.',count:state.attendance,target:12,icon:'🎓'},{title:'Find your people',text:'Build all three friendships to level 3.',count:state.friends.filter(x=>x>=3).length,target:3,icon:'🤝'},{title:'Make things happen',text:'Develop 60 skill points through campus activities.',count:state.skills,target:60,icon:'⚡'},{title:'Leave no corner unexplored',text:'Take an action at all 53 destinations in the supplied campus map.',count:state.visits.filter(id=>places.some(p=>p.id===id&&p.mapped)).length,target:53,icon:'🧭'}]}
function render(){if(!state)return;syncStudentLife();$('#profile').innerHTML=`<div class="profile-top"><div class="avatar">${state.avatar}</div><div><strong>${escapeHtml(state.name)}</strong><small>${escapeHtml(state.course)}</small></div></div><span class="student-tag">✦ FRESHER · SEMESTER 01</span>`;$('#greeting').textContent=tab==='campus'?`Make today a good story, ${state.name}.`:({life:'There’s a life between lectures.',goals:'A little progress, every day.',friends:'Campus is better together.',journal:'The story so far.'}[tab]);$('#subtitle').textContent=tab==='campus'?'Chase a first class. Find your people. Remember to eat.':'Every choice becomes part of your campus story.';$('#clock').innerHTML=`${state.hour>=18?'☾':'☀'} ${String(state.hour).padStart(2,'0')}:00<small>DAY ${state.day} / 28 · WEEK ${Math.ceil(state.day/7)}</small>`;$('#stats').innerHTML=[['Energy',state.energy,'#e1b362','⚡'],['Hunger',state.hunger,'#83a579','🍃'],['Mood',state.mood,'#ad91b0','✦'],['Projected GPA',gpa(),'#739aa1','▧']].map(([n,v,c,i])=>`<div class="stat" style="--meter:${c}"><label>${n}<span>${i}</span></label><strong>${n==='Projected GPA'?v.toFixed(2):Math.round(v)}<span style="font-size:10px;color:#9aa28f"> / ${n==='Projected GPA'?'5.0':'100'}</span></strong><div class="bar"><span style="width:${n==='Projected GPA'?v*20:v}%"></span></div></div>`).join('');$('#money').textContent=money(state.money);$('#allowance').textContent=state.finished?'Semester complete':`Next allowance: ${state.day<22?'Day '+(Math.floor((state.day-1)/7)*7+8):'no more this semester'} · ₦5,000`;document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));renderContent();renderLocation();$('#whisper').textContent=['Someone started a study group. Your future GPA says you should probably go.','The ICT Building has gigs. A little skill can go a long way.','Your roommates are planning a match. Good memories count too.','Exam season is coming. Consistency beats the last-minute all-nighter.'][Math.floor((state.day-1)/7)];if(state.finished)$('#sleep').textContent='✦ View semester results';else $('#sleep').innerHTML='☾ End day & recharge <span>→</span>';renderStudentLife()}
function mapSvg(){let trees='';for(let i=0;i<54;i++){const x=(i*137+20)%800,y=(i*79+25)%610;if(Math.abs(x-400)<58||Math.abs(y-305)<55)continue;trees+=`<g transform="translate(${x} ${y})"><ellipse cx="3" cy="13" rx="12" ry="5" fill="#61795116"/><path d="M0 0v17" stroke="#a2aa79" stroke-width="3"/><circle r="13" fill="${i%2?'#a4bb87':'#b6c997'}"/><circle cx="-4" cy="-3" r="6" fill="#c0d1a7"/></g>`}return `<svg viewBox="0 0 800 610" preserveAspectRatio="none" aria-hidden="true"><defs><pattern id="grass" width="22" height="22" patternUnits="userSpaceOnUse"><path d="M5 8l2-3m10 13l2-3" stroke="#dbe4c9" stroke-width="1"/></pattern></defs><rect width="800" height="610" fill="url(#grass)"/><path d="M-20 320Q210 280 400 310T820 280M390-20Q355 130 410 315T425 640" stroke="#c8cfb7" stroke-width="49" fill="none"/><path d="M-20 320Q210 280 400 310T820 280M390-20Q355 130 410 315T425 640" stroke="#faf6e4" stroke-width="39" fill="none"/><path d="M-20 320Q210 280 400 310T820 280M390-20Q355 130 410 315T425 640" stroke="#d8d9c5" stroke-width="1" stroke-dasharray="7 9" fill="none"/><path d="M185 150V295M550 130L430 170M170 410V318M635 370L555 305M410 500L420 400" stroke="#f7f3e0" stroke-width="16" fill="none"/><ellipse cx="415" cy="318" rx="58" ry="43" fill="#f6f2df" stroke="#d3d9c1" stroke-width="2"/><ellipse cx="415" cy="318" rx="35" ry="26" fill="#a8bc8b"/><ellipse cx="415" cy="313" rx="15" ry="11" fill="#c8dacf"/><path d="M415 298v15" stroke="#f8ffef" stroke-width="4"/>${trees}<rect x="300" y="456" width="174" height="113" rx="10" fill="#afc696" stroke="#e0e9d2" stroke-width="5"/><rect x="315" y="465" width="144" height="94" fill="none" stroke="#e5eedb" stroke-width="2"/><path d="M385 465v94" stroke="#e5eedb" stroke-width="2"/><circle cx="385" cy="512" r="18" fill="none" stroke="#e5eedb" stroke-width="2"/><text x="455" y="350" fill="#95a082" font-family="sans-serif" font-size="9" letter-spacing="3">FOUNDERS' WALK</text></svg>`}
function renderContent(){disposeGeoMap();const el=$('#content');if(tab==='campus'){renderCampus(el)}
else if(tab==='goals')el.innerHTML=`<div class="map-head" style="border-radius:10px;margin-bottom:16px"><div><h2>Semester 01</h2><small>Final exams after day 28. Projected GPA is an estimate.</small></div><span>${Math.round(state.day/28*100)}% THROUGH</span></div><div class="cards">${goals().map(g=>`<div class="card"><span class="big">${g.icon}</span><h3>${g.title}</h3><p>${g.text}</p><div class="progress-text"><span>${g.count>=g.target?'✓ ACHIEVED':'IN PROGRESS'}</span><span>${Math.min(g.count,g.target)} / ${g.target}</span></div><div class="bar"><span style="width:${Math.min(100,g.count/g.target*100)}%"></span></div></div>`).join('')}</div><div class="log">📖 Academics: ${state.attendance} lectures · ${state.assignments} assignments · ${Math.round(state.knowledge)} knowledge points.<small>GPA combines knowledge (up to 2.7), attendance (up to 1.1 for 18 lectures), and assignments (up to 0.9 for 10 submissions). Final exam wellbeing adds up to 0.3.</small></div>`;
else if(tab==='friends'){el.innerHTML=`<div class="cards">${people.map((p,i)=>`<div class="card"><span class="big">${p.icon}</span><h3>${p.name}</h3><span class="pill">${p.role}</span><p>${p.text}</p><small>Friendship ${state.friends[i]} / 5 ${state.friends[i]>=3?'· Close friend':''}</small><div class="bar" style="margin-top:10px"><span style="width:${state.friends[i]*20}%"></span></div><button class="secondary" data-friend="${i}" ${state.finished?'disabled':''}>${state.daily['friend'+i]?'Caught up today ✓':state.friends[i]>=5?'Hang out · 1 hr':'Get to know '+p.name+' · 1 hr'}</button></div>`).join('')}<div class="card"><span class="big">🌱</span><h3>Friendships take time.</h3><p>Catch up once per day to build a bond. Each conversation costs an hour and a little energy. These are fictional characters in your single-player story.</p></div></div>`;document.querySelectorAll('[data-friend]').forEach(b=>b.onclick=()=>friend(Number(b.dataset.friend)))}
else{el.innerHTML=`<div class="section-label" style="margin-bottom:18px">YOUR CAMPUS MEMORIES <span>${state.logs.length} ENTRIES</span></div>${state.logs.map(l=>`<div class="log"><small>DAY ${l.day} · ${String(l.hour).padStart(2,'0')}:00</small>${escapeHtml(l.text)}</div>`).join('')}`}}
function renderLocation(){renderGeoLocation()}

function travel(mode){const p=places.find(p=>p.id===selected);if(state.location===p.id)return;const cost=mode==='shuttle'?150:0,energy=mode==='shuttle'?-1:-5;if(!checkTime(1,energy,cost))return;state.hour++;state.money-=cost;state.energy=clamp(state.energy+energy);state.hunger=clamp(state.hunger-2);state.location=p.id;log(`Travelled to ${p.name} by ${mode}.`);save();render();ping();toast(`You’ve arrived at ${p.short}.`)}

function checkTime(hours,energy=0,cost=0){if(state.finished)return false;if(state.hour+hours>22){toast('It’s late. End the day to recharge.');return false}if(state.energy+energy<5){toast('You need more energy. Nap at the hostel or end the day.');return false}if(state.money<cost){toast('Not enough naira. Find a gig at the ICT Building.');return false}return true}
function effect(e){for(const[k,v]of Object.entries(e)){state[k]+=v;if(['energy','hunger','mood','social','knowledge','skills'].includes(k))state[k]=clamp(state[k])}}
function act(id){const p=places.find(p=>p.actions.some(a=>a[0]===id)),a=p.actions.find(a=>a[0]===id);if(state.finished)return;if(state.location!==p.id){toast('Travel to this location first.');return}const dailyKey=a[5].attendance?'lecture':id;if(['lecture','assignment','gig','enterprise'].includes(dailyKey)&&state.daily[dailyKey]){toast('You’ve done that today. Try something else.');return}if(!checkTime(a[3],a[5].energy||0,a[4]))return;state.money-=a[4];effect(a[5]);state.hour+=a[3];if(!('hunger'in a[5]))state.hunger=clamp(state.hunger-a[3]*2);if(state.hunger<15){state.energy=clamp(state.energy-6);state.mood=clamp(state.mood-5)}state.daily[dailyKey]=true;if(!state.visits.includes(p.id))state.visits.push(p.id);state.actions.push(id);studentActionEffect(p,a);log(a[6]);ping();save();render();toast(a[6]);if(state.actions.length%6===0&&!state.daily.event)eventEncounter()}
function friend(i){if(state.daily['friend'+i]){toast('You’ve caught up today. Come back tomorrow.');return}if(!checkTime(1,-6))return;state.hour++;state.energy=clamp(state.energy-6);state.hunger=clamp(state.hunger-3);state.mood=clamp(state.mood+8);state.social=clamp(state.social+12);state.friends[i]=Math.min(5,state.friends[i]+1);state.daily['friend'+i]=true;log(`Caught up with ${people[i].name}. ${['You found a shared interest.','A coffee and a good conversation.','You’re becoming real friends.','They trust you with their big plans.','A friend you can count on.'][state.friends[i]-1]}`);save();render();ping();toast('A little time together goes a long way.')}
const events=[{icon:'🌧️',title:'Rain check?',text:'A sudden downpour catches you between buildings. Tomi waves you over to a covered bench.',choices:[{text:'Wait it out together · 1 hr',hours:1,e:{social:10,mood:7}},{text:'Make a dash for it',hours:0,e:{energy:-8,mood:-3}}]}, {icon:'🎤',title:'An unexpected invitation',text:'There’s a small open-mic hangout after class. You could stay for a while, or keep your study promise.',choices:[{text:'Stay for the music · 1 hr',hours:1,e:{mood:14,social:8,energy:-5}},{text:'Revise your notes',hours:0,e:{knowledge:5,mood:-2}}]}, {icon:'🔌',title:'A helping hand',text:'A coursemate is stuck on a project. You recognise the problem. Do you lend a hand?',choices:[{text:'Help them work it out · 1 hr',hours:1,e:{skills:6,social:8,energy:-5}},{text:'Share a useful resource',hours:0,e:{social:3}}]}, {icon:'💸',title:'A little temptation',text:'Your group is ordering fancy drinks. Your wallet has opinions about this.',choices:[{text:'Join the order · ₦600',hours:0,cost:600,e:{mood:12,social:6,hunger:5}},{text:'Keep it budget friendly',hours:0,e:{mood:2}}]}];
function eventEncounter(){state.daily.event=true;const e=events[state.events++%events.length];save();show(`<span class="event-icon">${e.icon}</span><div class="eyebrow" style="margin-top:18px">A LITTLE CAMPUS MOMENT</div><h2>${e.title}</h2><p>${e.text}</p>${e.choices.map((c,i)=>`<button class="${i===0?'primary':'secondary'}" data-choice="${i}">${c.text}</button>`).join('')}<button class="secondary" id="skip">Keep going</button>`);$('#skip').onclick=close;document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{const c=e.choices[Number(b.dataset.choice)];if(!checkTime(c.hours,c.e.energy||0,c.cost||0))return;state.money-=c.cost||0;state.hour+=c.hours;effect(c.e);log(e.title+' '+c.text.replace(/ · .*/,''));close();save();render();ping()})}
function endDay(){if(state.finished){results();return}show(`<span class="event-icon">🌙</span><h2>Call it a day?</h2><p>Sleep restores your energy to 90, lowers hunger by 18, and returns you to the hostel and starts tomorrow at 08:00. ${state.day===28?'Your final exam and semester results are next.':'There are '+(28-state.day)+' days left after today.'}</p><button class="primary" id="confirmSleep">${state.day===28?'Finish the semester →':'Good night. Tomorrow is a fresh start. →'}</button><button class="secondary" id="cancelSleep">I still have things to do</button>`);$('#cancelSleep').onclick=close;$('#confirmSleep').onclick=()=>{close();if(state.day===28){state.finalGpa=Math.min(5,gpa()+.3*(state.energy+state.mood)/200);state.finished=true;log('Completed final exams. Semester one is in the books.');save();render();results();return}log('Ended the day and recharged for tomorrow.');state.day++;state.hour=8;state.location='hostel';state.energy=90;state.hunger=clamp(state.hunger-18);state.mood=clamp(state.mood+5);studentNight();state.daily={};if([8,15,22].includes(state.day)){state.money+=5000;log('Weekly allowance received: ₦5,000.');toast('New week, fresh start. ₦5,000 allowance received.')}else toast('Good morning! Your energy is restored.');save();render()}}
function results(){const n=goals().filter(g=>g.count>=g.target).length;show(`<span class="event-icon">🎓</span><div class="eyebrow" style="margin-top:16px">THE FIRST CHAPTER IS COMPLETE</div><h2>You made it, ${escapeHtml(state.name)}.</h2><p>28 days. Your choices. Your story.</p><div class="cards"><div class="card"><small>FINAL GPA</small><h2>${state.finalGpa.toFixed(2)} / 5</h2></div><div class="card"><small>GOALS ACHIEVED</small><h2>${n} / 4</h2></div></div><p>${state.finalGpa>=4.5?'First-class energy!':state.finalGpa>=3.5?'A strong academic foundation.':'There’s room to grow. Next time, balance lectures, assignments and study.'} You finished with ${money(state.money)} in your wallet, ${money(ensureStudentState().savings)} in virtual savings, and ${state.friends.filter(x=>x>=3).length} close friends.</p><button class="primary" id="review">Look back at my journal</button><button class="secondary" id="replay">Begin a new story</button>`);$('#review').onclick=()=>{close();tab='journal';render()};$('#replay').onclick=confirmNew}
function confirmNew(){show('<h2>A new beginning?</h2><p>This replaces the current saved character and semester on this browser.</p><button class="primary" id="resetYes">Start a new story</button><button class="secondary" id="resetNo">Keep my current story</button>');$('#resetNo').onclick=close;$('#resetYes').onclick=()=>{state=null;tab='campus';selected='hostel';zone='student';geoViewport=null;geoFilter='all';campusQuery='';intro()}}
$('#help').onclick=()=>{show('<div class="eyebrow">YOUR GUIDE TO CAMPUS</div><h2>Make your 28 days count.</h2><p>1. Use the mapped campus pins, the original Google map, or the building directory. Select a building, travel there, then choose an activity.<br>2. Actions spend game hours. Your day runs from 08:00 to 22:00.<br>3. Balance energy, hunger, and mood. Eat at the cafeteria and recharge at the hostel.<br>4. Attend lectures, submit assignments, and study to raise your GPA. Lectures, assignments, and gigs are once per day.<br>5. Earn virtual naira at the ICT Building or Industrial Park. Receive ₦5,000 allowance on days 8, 15, and 22.<br>6. Open your student phone for projects, savings, gigs, clubs, shopping, room upgrades and revision quizzes. Meet three fictional friends and complete semester goals. Finish day 28 to see your results.</p><p>Progress saves in this browser; clearing browser data removes it. Open Campus chat to sign in, meet real players, and manage cloud saves. All money is fictional.</p><button class="primary" id="understood">Let’s do this →</button>');$('#understood').onclick=close};$('#sound').onclick=()=>{audioOn=!audioOn;$('#sound').setAttribute('aria-pressed',audioOn);$('#sound').style.background=audioOn?'#e1ebd5':'transparent';ping();toast(audioOn?'Action sounds on':'Action sounds off')};$('#studentPhone').onclick=()=>openStudentPhone();$('#newgame').onclick=confirmNew;$('#sleep').onclick=endDay;document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;render()});
try{const raw=JSON.parse(localStorage.getItem(KEY));if(raw&&raw.version===1&&typeof raw.name==='string'&&Array.isArray(raw.friends)&&Array.isArray(raw.logs)&&Number.isFinite(raw.day)&&raw.day>=1&&raw.day<=28)state=raw}catch{}
if(state){state.location=places.some(p=>p.id===state.location)?state.location:'hostel';selected=state.location;zone=places.find(p=>p.id===selected).zone;render()}else{const placeholder=fresh('New student','Your next chapter','🧑🏾‍🎓');state=placeholder;render();state=null;intro()}

window.AbuadLifeGame={snapshot:()=>state?JSON.parse(JSON.stringify(state)):null,restore(value){if(!value||value.version!==1||typeof value.name!=='string'||!Array.isArray(value.friends)||!Array.isArray(value.logs))throw new Error('Invalid saved character');state=JSON.parse(JSON.stringify(value));selected=state.location||'hostel';close();save();render()}};
